add('13:a',['B2.2.2'],'A lower-triangular distance list d stores d[2][0]=7.4, d[2][1]=2.1 and d[1][0]=5.3. Indices0,1,2 represent Elm,Oak,Pine. State the distance between Elm and Pine.','7.4',[(1,'7.4')],[15],status='B',context_pages=[7,8],assets=[dict(kind='source_table',description='Original route names and lower triangular distance matrix',path='agents/chunk-2/agent-2-papers-b/papers/SRC-006/renders/page-7.png',source_pdf_page=7,visually_verified=True)],visual='Full original route table visually read.')
code1='''def valid_distances(d):
    for r in range(len(d)):
        for c in range(len(d)):
            if r <= c and d[r][c] != 0:
                return False
            if r > c and d[r][c] <= 0:
                return False
    return True'''
add('13:b',['B2.2.2','B2.3.2','B2.3.3'],'Construct a Python function valid_distances(d) for a nonempty square numeric nested list. It returns True exactly when all entries on/above the main diagonal are zero and all entries below it are positive.','One valid solution:\n'+code1,[(1,'Visits all rows.'),(1,'Visits all columns in each row.'),(1,'Rejects nonzero entries when r<=c.'),(1,'Rejects nonpositive entries when r>c.'),(1,'Returns True only after every required check passes.')],[15,16],status='B',new_command='Construct',code=code1,check='Executed valid3x3, wrong upper entry, zero lower entry and1x1 cases.',test_code=code1+'\nassert valid_distances([[0,0,0],[2,0,0],[3,4,0]])\nassert not valid_distances([[0,1],[2,0]])\nassert not valid_distances([[0,0],[0,0]])\nassert valid_distances([[0]])',context_pages=[7,8])
code2='''def distance(names, d, a, b):
    ia = ib = -1
    for i in range(len(names)):
        if names[i] == a: ia = i
        if names[i] == b: ib = i
    if ia == -1 or ib == -1:
        return None
    if ia < ib:
        ia, ib = ib, ia
    return d[ia][ib]'''
add('13:c',['B2.2.2','B2.3.2','B2.3.3','B2.4.2'],'Construct a Python function distance(names,d,a,b). names contains unique location names. Square d stores distances only below its main diagonal, with zeros on the diagonal. Return the distance between a and b, or None if either name is absent.','One valid solution:\n'+code2,[(1,'Initialize/search positions for both names.'),(1,'Traverse names correctly.'),(1,'Find both matching indices.'),(1,'Handle either missing name with None.'),(1,'Choose larger index as row and smaller as column.'),(1,'Return correct nested-list entry, including identical-location zero.')],[17,18],status='B',new_command='Construct',code=code2,context_pages=[7,8],check='Executed both input orders, same location, missing first/second names.',test_code=code2+'\nn=["Elm","Oak","Pine"];d=[[0,0,0],[2,0,0],[5,3,0]]\nassert distance(n,d,"Elm","Pine")==5\nassert distance(n,d,"Pine","Elm")==5\nassert distance(n,d,"Elm","Elm")==0\nassert distance(n,d,"X","Pine") is None\nassert distance(n,d,"Elm","X") is None')
